        .collect()
}

fn tool() -> Command {
    Command::new("tool")
        .subcommand(
            Command::new("remote")
                .visible_alias("r")
                .subcommand(
                    Command::new("add")
                        .visible_alias("a")
                        .arg(clap::Arg::new("mode").value_parser(["fast", "safe"])),
                ),
        )
        .subcommand(Command::new("status"))
}

#[test]
fn repro_alias_paths() {
    // canonical path: tool remote add [TAB]
    let mut cmd = tool();
    let r = complete_raw(&mut cmd, &["tool", "remote", "add", ""], 3);
    println!("canonical remote add: {r:?}");

    // alias first level: tool r add [TAB]
    let mut cmd = tool();
    let r = complete_raw(&mut cmd, &["tool", "r", "add", ""], 3);
    println!("r add: {r:?}");

    // alias second level: tool remote a [TAB]
    let mut cmd = tool();
    let r = complete_raw(&mut cmd, &["tool", "remote", "a", ""], 3);
    println!("remote a: {r:?}");

    // both aliases: tool r a [TAB]
    let mut cmd = tool();
    let r = complete_raw(&mut cmd, &["tool", "r", "a", ""], 3);
    println!("r a: {r:?}");

    // after escape: tool r a -- [TAB]
    let mut cmd = tool();
    let r = complete_raw(&mut cmd, &["tool", "r", "a", "--", ""], 4);
    println!("r a -- : {r:?}");

    // root empty prefix: tool [TAB]
    let mut cmd = tool();
    let r = complete_raw(&mut cmd, &["tool", ""], 1);
    println!("root: {r:?}");

    // partial alias must not match: tool remo [TAB] ok, tool re [TAB] should list remote
    let mut cmd = tool();
    let r = complete_raw(&mut cmd, &["tool", "re", ""], 2);
    println!("after partial 're' (completing next): {r:?}");

    // unknown subcommand: tool bogus [TAB]
    let mut cmd = tool();
    let r = complete_raw(&mut cmd, &["tool", "bogus", ""], 2);
    println!("bogus: {r:?}");

    // unknown alias name as completed token: tool x [TAB]
    let mut cmd = tool();
    let r = complete_raw(&mut cmd, &["tool", "x"], 1);
    println!("unknown x completion: {r:?}");
}

